def maxSubarrayMedian(nums, k):
    n = len(nums)
    vals = sorted(set(nums))

    def ok(m):
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + (1 if x >= m else -1)
        best = 10 ** 9
        for j in range(k, n + 1):
            best = min(best, pre[j - k])
            if pre[j] - best >= 0:
                return True
        return False

    lo, hi = 0, len(vals) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(vals[mid]):
            lo = mid
        else:
            hi = mid - 1
    return vals[lo]
